def page_count(total_items, per_page):
    if total_items <= 0:
        return 0
    return (total_items + per_page - 1) // per_page

def windows(items, size):
    result = []
    for i in range(0, len(items), size):
        chunk = items[i:i + size]
        result.append(chunk)
    return result

def nth_from_end(items, n):
    if n > len(items) or n <= 0:
        return None
    return items[-n]

def truncate_words(text, limit):
    words = text.split()
    if len(words) > limit:
        truncated = words[:limit]
        if len(truncated) < len(words):
            truncated.append('...')
        return ' '.join(truncated)
    return text

def bytes_human(n):
    if n == 0:
        return '0.0 B'
    elif n < 1024:
        return f'{n}.0 B'
    elif n < 1048576:
        return f'{n / 1024:.1f} KB'
    elif n < 1073741824:
        return f'{n / 1048576:.1f} MB'
    else:
        return f'{n / 1073741824:.1f} GB'

def insert_sorted(items, value):
    for i in range(len(items)):
        if items[i] > value:
            items.insert(i + 1, value)
            return items
    items.append(value)
    return items

def clip_exclusive(index, length):
    if index < 0:
        index = 0
    elif index >= length:
        index = length - 1
    return index

def columns(items, n):
    result = [[] for _ in range(n)]
    for i, item in enumerate(items):
        result[i % n].append(item)
    return result

def countdown(start):
    if start <= 0:
        return []
    result = []
    for i in range(start, 0, -1):
        result.append(i)
    return result

def trim_to_fit(words, width):
    trimmed_words = []
    current_line = ""
    for word in words:
        if len(current_line) + len(word) + 1 <= width:
            if current_line:
                current_line += " "
            current_line += word
        else:
            trimmed_words.append(current_line)
            current_line = word
    if current_line:
        trimmed_words.append(current_line)
    return trimmed_words

def progress(done, total, width):
    filled = int((done / total) * width)
    return filled
